{"cmd":"cat > /root/local.rules <<'EOF'
# Custom telemetry exfil detection
alert http any any -> any any (
  msg:"TLM telemetry exfil pattern";
  flow:established,to_server;

  http.method;
  content:"POST";

  http.uri;
  pcre:"/^\\/telemetry\\/v2\\/report$/";

  http.header;
  content:"X-TLM-Mode|3a| exfil";
  nocase;

  http_client_body;
  pcre:"/blob=[A-Za-z0-9+\\/]{80,}={0,2}(?:&|\\s|$)/";

  http_client_body;
  pcre:"/sig=[0-9a-fA-F]{64}(?:&|\\s|$)/";

  sid:1000001;
  rev:1;
)
EOF"}
